using EEMS.Modules.Elections.Infrastructure;using EEMS.Modules.Events.Domain;using EEMS.Modules.Events.Infrastructure;using EEMS.Modules.Geography.Infrastructure;using EEMS.Modules.Identity.Infrastructure;using EEMS.SharedKernel.Tenancy;using Microsoft.EntityFrameworkCore;
namespace EEMS.Api.Events;
public sealed class EventOperationsService(EventsDbContext db,ElectionsDbContext elections,GeographyDbContext geography,IdentityDbContext identity,ITenantContext tenant){
public async Task<EventWorkspace?> Get(Guid electionId,CancellationToken ct){if(!await elections.Elections.AnyAsync(x=>x.TenantId==tenant.TenantId&&x.Id==electionId,ct))return null;var meetings=await db.Meetings.Where(x=>x.TenantId==tenant.TenantId&&x.ElectionId==electionId).OrderBy(x=>x.StartsAtUtc).ToListAsync(ct);var ids=meetings.Select(x=>x.Id).ToArray();var participants=await db.MeetingParticipants.Where(x=>x.TenantId==tenant.TenantId&&ids.Contains(x.MeetingId)).ToListAsync(ct);return new(await db.EventTypes.Where(x=>x.IsActive).Select(x=>new Ref(x.Id,x.Code,x.Name,false)).ToListAsync(ct),await db.EventStates.Where(x=>x.IsActive).Select(x=>new Ref(x.Id,x.Code,x.Name,x.IsTerminal)).ToListAsync(ct),await geography.Areas.Where(x=>x.IsActive).Select(x=>new AreaRef(x.Id,x.NameEn??x.NameBn)).ToListAsync(ct),await identity.Users.Where(x=>x.IsActive).Select(x=>new Named(x.Id,x.DisplayName)).ToListAsync(ct),await db.Venues.Where(x=>x.TenantId==tenant.TenantId&&x.IsActive).Select(x=>new VenueSummary(x.Id,x.AreaId,x.Name,x.Address,x.Capacity)).ToListAsync(ct),await db.Events.Where(x=>x.TenantId==tenant.TenantId&&x.ElectionId==electionId).OrderBy(x=>x.StartsAtUtc).Select(x=>new EventSummary(x.Id,x.EventTypeId,x.StateId,x.AreaId,x.VenueId,x.Title,x.StartsAtUtc,x.EndsAtUtc,x.CompletionReport,x.Version)).ToListAsync(ct),meetings.Select(x=>new MeetingSummary(x.Id,x.EventId,x.Title,x.Agenda,x.Minutes,x.StartsAtUtc,x.EndsAtUtc,participants.Count(p=>p.MeetingId==x.Id),participants.Count(p=>p.MeetingId==x.Id&&p.Attended))).ToArray());}
public async Task<VenueSummary?> AddVenue(long areaId,string name,string address,int? capacity,CancellationToken ct){if(!await geography.Areas.AnyAsync(x=>x.Id==areaId&&x.IsActive,ct))return null;var x=Venue.Create(tenant.TenantId,areaId,name,address,capacity);db.Venues.Add(x);await db.SaveChangesAsync(ct);return new(x.Id,x.AreaId,x.Name,x.Address,x.Capacity);}
public async Task<EventSummary?> AddEvent(Guid electionId,CreateEvent c,CancellationToken ct){if(!await elections.Elections.AnyAsync(x=>x.TenantId==tenant.TenantId&&x.Id==electionId,ct)||!await db.EventTypes.AnyAsync(x=>x.Id==c.TypeId&&x.IsActive,ct)||!await db.EventStates.AnyAsync(x=>x.Id==c.StateId&&x.IsActive,ct))return null;var x=CampaignEvent.Create(tenant.TenantId,electionId,c.TypeId,c.StateId,c.AreaId,c.Title,c.Starts,c.Ends,c.VenueId);db.Events.Add(x);await db.SaveChangesAsync(ct);return E(x);}
public async Task<EventSummary?> Complete(Guid electionId,Guid id,int version,string report,CancellationToken ct){var x=await db.Events.SingleOrDefaultAsync(x=>x.TenantId==tenant.TenantId&&x.ElectionId==electionId&&x.Id==id,ct);var state=await db.EventStates.Where(x=>x.IsActive&&x.IsTerminal&&x.Code=="COMPLETED").FirstOrDefaultAsync(ct);if(x is null||state is null||x.Version!=version)return null;x.Complete(report,state.Id);await db.SaveChangesAsync(ct);return E(x);}
public async Task<MeetingSummary?> AddMeeting(Guid electionId,Guid userId,CreateMeeting c,CancellationToken ct){if(!await elections.Elections.AnyAsync(x=>x.TenantId==tenant.TenantId&&x.Id==electionId,ct)||(c.EventId.HasValue&&!await db.Events.AnyAsync(x=>x.TenantId==tenant.TenantId&&x.ElectionId==electionId&&x.Id==c.EventId,ct)))return null;var x=Meeting.Create(tenant.TenantId,electionId,userId,c.Title,c.Agenda,c.Starts,c.Ends,c.EventId);db.Meetings.Add(x);await db.SaveChangesAsync(ct);return new(x.Id,x.EventId,x.Title,x.Agenda,null,x.StartsAtUtc,x.EndsAtUtc,0,0);}
public async Task<bool> AddParticipant(Guid electionId,Guid meetingId,Guid userId,CancellationToken ct){if(!await db.Meetings.AnyAsync(x=>x.TenantId==tenant.TenantId&&x.ElectionId==electionId&&x.Id==meetingId,ct)||!await identity.Users.AnyAsync(x=>x.Id==userId&&x.IsActive,ct)||await db.MeetingParticipants.AnyAsync(x=>x.TenantId==tenant.TenantId&&x.MeetingId==meetingId&&x.UserId==userId,ct))return false;db.MeetingParticipants.Add(MeetingParticipant.Create(tenant.TenantId,meetingId,userId));await db.SaveChangesAsync(ct);return true;}
public async Task<bool> Attend(Guid electionId,Guid meetingId,Guid userId,CancellationToken ct){var x=await(from p in db.MeetingParticipants join m in db.Meetings on p.MeetingId equals m.Id where p.TenantId==tenant.TenantId&&p.MeetingId==meetingId&&p.UserId==userId&&m.ElectionId==electionId select p).SingleOrDefaultAsync(ct);if(x is null)return false;x.MarkAttended();await db.SaveChangesAsync(ct);return true;}private static EventSummary E(CampaignEvent x)=>new(x.Id,x.EventTypeId,x.StateId,x.AreaId,x.VenueId,x.Title,x.StartsAtUtc,x.EndsAtUtc,x.CompletionReport,x.Version);}
public sealed record EventWorkspace(IReadOnlyList<Ref> Types,IReadOnlyList<Ref> States,IReadOnlyList<AreaRef> Areas,IReadOnlyList<Named> Users,IReadOnlyList<VenueSummary> Venues,IReadOnlyList<EventSummary> Events,IReadOnlyList<MeetingSummary> Meetings);public sealed record Ref(short Id,string Code,string Name,bool IsTerminal);public sealed record AreaRef(long Id,string Name);public sealed record Named(Guid Id,string Name);public sealed record VenueSummary(Guid VenueId,long AreaId,string Name,string Address,int? Capacity);public sealed record EventSummary(Guid EventId,short EventTypeId,short StateId,long AreaId,Guid? VenueId,string Title,DateTimeOffset StartsAtUtc,DateTimeOffset EndsAtUtc,string? CompletionReport,int Version);public sealed record MeetingSummary(Guid MeetingId,Guid? EventId,string Title,string Agenda,string? Minutes,DateTimeOffset StartsAtUtc,DateTimeOffset EndsAtUtc,int ParticipantCount,int AttendedCount);public sealed record CreateEvent(short TypeId,short StateId,long AreaId,Guid? VenueId,string Title,DateTimeOffset Starts,DateTimeOffset Ends);public sealed record CreateMeeting(Guid? EventId,string Title,string Agenda,DateTimeOffset Starts,DateTimeOffset Ends);
